import{_ as e,o as i,c as o,ag as d}from"./chunks/framework.K4imGPUB.js";const _=JSON.parse('{"title":"Linux 常用命令使用手册","description":"","frontmatter":{},"headers":[],"relativePath":"docs/operation/Linux/常用命令.md","filePath":"docs/operation/Linux/常用命令.md"}'),a={name:"docs/operation/Linux/常用命令.md"};function c(r,l,t,u,h,n){return i(),o("div",null,[...l[0]||(l[0]=[d('<h1 id="linux-常用命令使用手册" tabindex="-1">Linux 常用命令使用手册 <a class="header-anchor" href="#linux-常用命令使用手册" aria-label="Permalink to &quot;Linux 常用命令使用手册&quot;">​</a></h1><h2 id="_1-文件与目录操作" tabindex="-1">1. 文件与目录操作 <a class="header-anchor" href="#_1-文件与目录操作" aria-label="Permalink to &quot;1. 文件与目录操作&quot;">​</a></h2><h3 id="_1-1-目录操作" tabindex="-1">1.1 目录操作 <a class="header-anchor" href="#_1-1-目录操作" aria-label="Permalink to &quot;1.1 目录操作&quot;">​</a></h3><ul><li><code>pwd</code>: 显示当前工作目录</li><li><code>cd [目录]</code>: 切换目录 <ul><li><code>cd ..</code>: 返回上级目录</li><li><code>cd ~</code>: 返回用户主目录</li><li><code>cd -</code>: 返回上一个工作目录</li></ul></li><li><code>ls</code>: 列出目录内容 <ul><li><code>ls -l</code>: 详细信息</li><li><code>ls -a</code>: 显示所有文件（包括隐藏文件）</li><li><code>ls -h</code>: 以人类可读的方式显示文件大小</li><li><code>ls -R</code>: 递归显示子目录</li></ul></li><li><code>mkdir [目录名]</code>: 创建目录 <ul><li><code>mkdir -p</code>: 创建多级目录</li></ul></li><li><code>rmdir [目录名]</code>: 删除空目录</li><li><code>tree</code>: 以树形结构显示目录</li><li><code>mv</code> : 移动或重命名文件 <ul><li><code>mv old_file new_file</code>: 重命名文件</li><li><code>mv old_dir new_dir</code>: 移动目录</li><li><code>mv old_file new_dir/new_file</code>: 移动文件</li><li><code>mv old_file new_dir/</code>: 移动文件并重命名</li><li><code>mv old_dir/old_file new_file</code>: 移动文件并重命名</li></ul></li></ul><h3 id="_1-2-文件操作" tabindex="-1">1.2 文件操作 <a class="header-anchor" href="#_1-2-文件操作" aria-label="Permalink to &quot;1.2 文件操作&quot;">​</a></h3><ul><li><code>touch [文件名]</code>: 创建空文件或更新文件时间戳</li><li><code>cp [源文件] [目标文件]</code>: 复制文件 <ul><li><code>cp -r</code>: 递归复制目录</li><li><code>cp -p</code>: 保留文件属性</li></ul></li><li><code>mv [源文件] [目标文件]</code>: 移动或重命名文件</li><li><code>rm [文件]</code>: 删除文件 <ul><li><code>rm -r</code>: 递归删除目录</li><li><code>rm -f</code>: 强制删除</li></ul></li><li><code>cat [文件]</code>: 查看文件内容</li><li><code>less [文件]</code>: 分页查看文件内容</li><li><code>head [文件]</code>: 查看文件开头</li><li><code>tail [文件]</code>: 查看文件结尾 <ul><li><code>tail -f</code>: 实时查看文件更新</li></ul></li></ul><h2 id="_2-文件权限管理" tabindex="-1">2. 文件权限管理 <a class="header-anchor" href="#_2-文件权限管理" aria-label="Permalink to &quot;2. 文件权限管理&quot;">​</a></h2><h3 id="_2-1-权限设置" tabindex="-1">2.1 权限设置 <a class="header-anchor" href="#_2-1-权限设置" aria-label="Permalink to &quot;2.1 权限设置&quot;">​</a></h3><ul><li><code>chmod [权限] [文件]</code>: 修改文件权限 <ul><li>数字方式：<code>chmod 755 file</code></li><li>符号方式：<code>chmod u+x file</code></li></ul></li><li><code>chown [用户:组] [文件]</code>: 修改文件所有者</li><li><code>chgrp [组] [文件]</code>: 修改文件所属组</li></ul><h3 id="_2-2-权限说明" tabindex="-1">2.2 权限说明 <a class="header-anchor" href="#_2-2-权限说明" aria-label="Permalink to &quot;2.2 权限说明&quot;">​</a></h3><ul><li>读(r) = 4</li><li>写(w) = 2</li><li>执行(x) = 1</li><li>常见权限组合： <ul><li>755: rwxr-xr-x</li><li>644: rw-r--r--</li><li>777: rwxrwxrwx</li></ul></li></ul><h2 id="_3-系统管理" tabindex="-1">3. 系统管理 <a class="header-anchor" href="#_3-系统管理" aria-label="Permalink to &quot;3. 系统管理&quot;">​</a></h2><h3 id="_3-1-进程管理" tabindex="-1">3.1 进程管理 <a class="header-anchor" href="#_3-1-进程管理" aria-label="Permalink to &quot;3.1 进程管理&quot;">​</a></h3><ul><li><code>ps</code>: 显示进程状态 <ul><li><code>ps aux</code>: 显示所有进程</li><li><code>ps -ef</code>: 显示所有进程</li></ul></li><li><code>top</code>: 实时显示进程状态</li><li><code>kill [进程ID]</code>: 终止进程</li><li><code>killall [进程名]</code>: 终止指定名称的进程</li><li><code>nice</code>: 调整进程优先级</li></ul><h3 id="_3-2-系统信息" tabindex="-1">3.2 系统信息 <a class="header-anchor" href="#_3-2-系统信息" aria-label="Permalink to &quot;3.2 系统信息&quot;">​</a></h3><ul><li><code>uname</code>: 显示系统信息</li><li><code>df</code>: 显示磁盘使用情况</li><li><code>du</code>: 显示目录大小</li><li><code>free</code>: 显示内存使用情况</li><li><code>uptime</code>: 显示系统运行时间</li><li><code>date</code>: 显示或设置系统时间</li></ul><h2 id="_4-网络操作" tabindex="-1">4. 网络操作 <a class="header-anchor" href="#_4-网络操作" aria-label="Permalink to &quot;4. 网络操作&quot;">​</a></h2><h3 id="_4-1-网络配置" tabindex="-1">4.1 网络配置 <a class="header-anchor" href="#_4-1-网络配置" aria-label="Permalink to &quot;4.1 网络配置&quot;">​</a></h3><ul><li><code>ifconfig</code>: 显示网络接口信息</li><li><code>ip addr</code>: 显示网络接口信息（新版）</li><li><code>ping [主机]</code>: 测试网络连通性</li><li><code>netstat</code>: 显示网络状态 <ul><li><code>netstat -tulpn</code>: 显示所有监听端口</li></ul></li></ul><h3 id="_4-2-远程连接" tabindex="-1">4.2 远程连接 <a class="header-anchor" href="#_4-2-远程连接" aria-label="Permalink to &quot;4.2 远程连接&quot;">​</a></h3><ul><li><code>ssh [用户@主机]</code>: SSH远程登录</li><li><code>scp [源文件] [目标位置]</code>: 远程文件复制</li><li><code>rsync</code>: 远程文件同步</li></ul><h2 id="_5-文本处理" tabindex="-1">5. 文本处理 <a class="header-anchor" href="#_5-文本处理" aria-label="Permalink to &quot;5. 文本处理&quot;">​</a></h2><h3 id="_5-1-文本编辑" tabindex="-1">5.1 文本编辑 <a class="header-anchor" href="#_5-1-文本编辑" aria-label="Permalink to &quot;5.1 文本编辑&quot;">​</a></h3><ul><li><code>vim</code>: 文本编辑器</li><li><code>nano</code>: 简单文本编辑器</li><li><code>sed</code>: 流编辑器</li><li><code>awk</code>: 文本处理工具</li></ul><h3 id="_5-2-文本搜索" tabindex="-1">5.2 文本搜索 <a class="header-anchor" href="#_5-2-文本搜索" aria-label="Permalink to &quot;5.2 文本搜索&quot;">​</a></h3><ul><li><code>grep [模式] [文件]</code>: 搜索文本 <ul><li><code>grep -r</code>: 递归搜索</li><li><code>grep -i</code>: 忽略大小写</li></ul></li><li><code>find [路径] [条件]</code>: 查找文件 <ul><li><code>find . -name &quot;*.txt&quot;</code>: 查找txt文件</li><li><code>find . -type f</code>: 查找普通文件</li></ul></li></ul><h2 id="_6-压缩与打包" tabindex="-1">6. 压缩与打包 <a class="header-anchor" href="#_6-压缩与打包" aria-label="Permalink to &quot;6. 压缩与打包&quot;">​</a></h2><h3 id="_6-1-压缩命令" tabindex="-1">6.1 压缩命令 <a class="header-anchor" href="#_6-1-压缩命令" aria-label="Permalink to &quot;6.1 压缩命令&quot;">​</a></h3><ul><li><code>gzip [文件]</code>: 压缩文件</li><li><code>gunzip [文件]</code>: 解压文件</li><li><code>bzip2 [文件]</code>: 压缩文件</li><li><code>bunzip2 [文件]</code>: 解压文件</li><li><code>zip [压缩包] [文件]</code>: 创建zip压缩包</li><li><code>unzip [压缩包]</code>: 解压zip文件</li></ul><h3 id="_6-2-打包命令" tabindex="-1">6.2 打包命令 <a class="header-anchor" href="#_6-2-打包命令" aria-label="Permalink to &quot;6.2 打包命令&quot;">​</a></h3><ul><li><code>tar -cvf [包名] [文件]</code>: 打包</li><li><code>tar -xvf [包名]</code>: 解包</li><li><code>tar -czvf [包名] [文件]</code>: 打包并压缩</li><li><code>tar -xzvf [包名]</code>: 解压并解包</li></ul><h2 id="_7-用户管理" tabindex="-1">7. 用户管理 <a class="header-anchor" href="#_7-用户管理" aria-label="Permalink to &quot;7. 用户管理&quot;">​</a></h2><h3 id="_7-1-用户操作" tabindex="-1">7.1 用户操作 <a class="header-anchor" href="#_7-1-用户操作" aria-label="Permalink to &quot;7.1 用户操作&quot;">​</a></h3><ul><li><code>useradd [用户名]</code>: 添加用户</li><li><code>userdel [用户名]</code>: 删除用户</li><li><code>passwd [用户名]</code>: 修改密码</li><li><code>su [用户名]</code>: 切换用户</li><li><code>sudo</code>: 以管理员权限执行命令</li></ul><h3 id="_7-2-组操作" tabindex="-1">7.2 组操作 <a class="header-anchor" href="#_7-2-组操作" aria-label="Permalink to &quot;7.2 组操作&quot;">​</a></h3><ul><li><code>groupadd [组名]</code>: 添加组</li><li><code>groupdel [组名]</code>: 删除组</li><li><code>usermod -G [组名] [用户名]</code>: 将用户添加到组</li></ul><h2 id="_8-其他实用命令" tabindex="-1">8. 其他实用命令 <a class="header-anchor" href="#_8-其他实用命令" aria-label="Permalink to &quot;8. 其他实用命令&quot;">​</a></h2><h3 id="_8-1-系统维护" tabindex="-1">8.1 系统维护 <a class="header-anchor" href="#_8-1-系统维护" aria-label="Permalink to &quot;8.1 系统维护&quot;">​</a></h3><ul><li><code>shutdown</code>: 关机</li><li><code>reboot</code>: 重启</li><li><code>init</code>: 切换运行级别</li><li><code>service</code>: 管理系统服务</li></ul><h3 id="_8-2-日志查看" tabindex="-1">8.2 日志查看 <a class="header-anchor" href="#_8-2-日志查看" aria-label="Permalink to &quot;8.2 日志查看&quot;">​</a></h3><ul><li><code>journalctl</code>: 查看系统日志</li><li><code>dmesg</code>: 查看内核日志</li><li><code>tail -f /var/log/syslog</code>: 实时查看系统日志</li></ul><h3 id="_8-3-环境变量" tabindex="-1">8.3 环境变量 <a class="header-anchor" href="#_8-3-环境变量" aria-label="Permalink to &quot;8.3 环境变量&quot;">​</a></h3><ul><li><code>echo $PATH</code>: 显示环境变量</li><li><code>export</code>: 设置环境变量</li><li><code>source</code>: 重新加载配置文件</li></ul><h2 id="_9-常用快捷键" tabindex="-1">9. 常用快捷键 <a class="header-anchor" href="#_9-常用快捷键" aria-label="Permalink to &quot;9. 常用快捷键&quot;">​</a></h2><ul><li><code>Ctrl + C</code>: 中断当前命令</li><li><code>Ctrl + D</code>: 退出当前终端</li><li><code>Ctrl + L</code>: 清屏</li><li><code>Ctrl + A</code>: 移动到行首</li><li><code>Ctrl + E</code>: 移动到行尾</li><li><code>Ctrl + U</code>: 删除光标前的所有内容</li><li><code>Ctrl + K</code>: 删除光标后的所有内容</li><li><code>Ctrl + R</code>: 搜索历史命令</li></ul>',45)])])}const f=e(a,[["render",c]]);export{_ as __pageData,f as default};
